unit(id=2581, th='1', no=2, title='What\'s in a Name?', cb='4–5', wb='4–5', skill='Grammar',
 vocab=[('brand name','the name a company gives to its product'),('trademark','a name or symbol owned by a company'),('logo','a symbol that represents a company'),('ownership','the fact of owning something'),('consumer','a person who buys and uses products'),('founder','a person who starts a company'),('global','all over the world')],
 grammar='Past simple and past simple passive.',
 focus='Past simple vs past simple passive; reading about the history of branding.',
 outcomes=['Discuss brand names and Juliet\'s quotation "What\'s in a name?"','Read a text about the history of branding and answer questions.','Differentiate between the past simple (completed actions, sequences, past states) and the past simple passive (focus on the action / unknown doer).','Change active sentences into the past simple passive.','Ask and answer questions to complete information (information gap).'],
 warm='CB p.4 Ex 1: Do you buy things because of the brand name? Which brand names do you like or dislike?',
 steps=[('Discussion',5,['CB p.4 Ex 1 – Juliet\'s quotation and brand names.']),
        ('Reading',10,['CB p.4 Ex 2: A Short History of Branding – the Chevrolet Nova mistake, Adidas (Adi + Dassler), Coca-Cola.']),
        ('Grammar Recall',12,['CB p.5: match sentences to usages (Microsoft was founded in 1975 by Bill Gates; The Wright brothers first built a plane and then flew it…).','Ex 3: find past simple and past simple passive verbs in the text and sort them.']),
        ('Practice',8,['Ex 4: irregular verb chain (make → was made); rewrite sentences in the passive (Adolf Dassler founded Adidas → Adidas was founded by Adolf Dassler).']),
        ('Information gap',5,['Ex 5: Communication Activity (WB p.64): ask questions to complete company histories.'])],
 formative='Mini-whiteboards: students transform active sentences to passive; check was/were and participles.',
 enrich='High achievers: research and write the history of an Omani brand (Oman Air, Omantel) using the passive.\nLow achievers: complete passive sentences with given participles.',
 closing='Each student says one sentence about a famous company using the passive (… was founded in … by …).',
 homework='Workbook pp.4–5.',
 misc='Students write "was founded by" for things the subject did itself: "Bill Gates was founded Microsoft".\nStudents use the past simple form instead of the participle: "was chose" → was chosen.',
 hw=('Rewrite in the passive: Oman Air chose a new logo.','A new logo was chosen by Oman Air.','Why did the Chevrolet Nova not sell well in Spanish-speaking countries?','"No va" means "it doesn\'t go" in Spanish.'),
 bank=['m: Gن|Microsoft ______ in 1975 by Bill Gates.|was founded|founded|is founded',
       'm: Gم|Adidas ______ from the name of its founder, Adolf Dassler.|was taken|took|was took',
       'm: Gم|The Wright brothers first ______ a plane and then flew it.|built|were built|build',
       'm: Gم|Mobile phones ______ until the late twentieth century.|were not created|did not create|not created',
       'm: Vم|Companies use slogans and ______ to persuade us to buy their products.|logos|rituals|routes',
       'm: Rم|Chevrolet chose the name "Nova" for a new car. "Nova" is from Latin and means "new", but in Spanish "no va" means "it doesn\'t go". // Why was "Nova" a bad name in Spanish-speaking markets?|It sounded like "it doesn\'t go".|It was too long.|It was a Latin word.',
       'w: Rن1|Branding is not new. In ancient times, people burned marks on things and animals to show ownership. But branding in business was not developed until the early nineteenth century, when trademarks and logos were introduced. // Statement: Trademarks and logos were introduced in ancient times. (True or False?) => False',
       'w: Gم1|Complete with ONE word: The first telephone ______ invented by Alexander Graham Bell. => was',
       'w: Vن1|Complete the word: (noun) a person who buys and uses products. e.g. The brand burns a mark into the mind of the cons_____. => consumer',
       'l: Wم5|Write an informative paragraph (at least 100 words) about the history of a famous company or brand. Use the past simple and the past simple passive. => Name and founder ;; Dates and key events ;; Past simple and passive used correctly ;; Logical order ;; At least 100 words'],
 study=dict(intro='In this lesson you read about the history of branding and review the past simple and the past simple passive.',
  O=[('Use the past simple.',['Completed actions: Alexander Graham Bell invented the telephone.','Actions in sequence: They built a plane and then flew it.','Past states: The Omanis were great traders.']),
     ('Use the past simple passive.',['was / were + past participle.','When the action is more important than the doer: Microsoft was founded in 1975.','When we don\'t know who did it.']),
     ('Understand branding.',['brand name, trademark, logo, slogan.','The right name must "travel well" in other languages.'])],
  R=['Passive: was/were + past participle (+ by…).','Irregular participles: chose → chosen, took → taken.'],
  focus='Past simple active vs passive.', weak=['Grammar'],
  simple='Active: Adolf Dassler founded Adidas.\nPassive: Adidas was founded by Adolf Dassler.\nThe object becomes the subject.',
  F=[('Coca-Cola ______ (invent) in 1886.','was invented'),('The company ______ (choose) a new logo last year.','chose'),('The logo ______ (design) by a young artist.','was designed'),('Mobile phones ______ (not / create) until the late 20th century.','were not created'),('Bill Gates ______ (found) Microsoft.','founded')],
  C=[('The Omanis (were / was) great traders.','were'),('Adidas was (founded / found) by Dassler.','founded'),('The name (was chosen / chose) carefully.','was chosen'),('Bell (invented / was invented) the telephone.','invented'),('The new car (was called / called) Nova.','was called')],
  S=[('Where did the name Adidas come from?','Adi (Adolf\'s nickname) + Das (from Dassler)'),('Rewrite: People in ancient times used branding.','Branding was used in ancient times.'),('Why do global brand names need to "travel well"?','because the name must be suitable in other languages and countries')]),
 games=dict(claims=[('"Microsoft was founded in 1975" is passive.',True,'was + past participle.'),('Branding in business started in the 1800s.',True,'Trademarks and logos were introduced in the early nineteenth century.'),('"The car was chose" is correct.',False,'Use the participle: was chosen.'),('"Nova" means "it doesn\'t go" in Latin.',False,'It means "new" in Latin.')],
  links=[('Adolf Dassler','Adidas','The brand was named after him.'),('Spanish markets','Chevrolet Nova failed','"No va" = it doesn\'t go.')],
  seq=('Making a passive sentence',['Find the object','Put it first','Add was/were','Add the past participle','Add by + doer'])),
 cando=['أميّز بين الماضي البسيط والماضي البسيط المبني للمجهول وأستخدمهما.','أحوّل جملًا من المبني للمعلوم إلى المبني للمجهول في الماضي.','أقرأ نصًا عن تاريخ العلامات التجارية وأجيب عن أسئلته.','أطرح أسئلة لاستكمال معلومات ناقصة مع زميلي.'])

